_DEFAULT_BASE_URL = "http://localhost:1234"


def _fallback_models():
    """Baked-in benchmark model list when LM Studio is unreachable."""
    try:
        from localbenchmark.localbenchmark import MODELS

        return list(MODELS)
    except Exception:
        pass
    try:
        from llm_coding_benchmark import MODELS

        return list(MODELS)
    except Exception:
        return []


def list_available_models(base_url=None, api_key=None):
    """
    Return model keys from the server, or the benchmark default list.

    Tries LM Studio's GET {base_url}/api/v1/models first, then the
    OpenAI-compatible GET {base_url}/v1/models (llama.cpp, vLLM, Ollama, ...),
    so the menu matches what the server actually offers.
    """
    base = (base_url or _DEFAULT_BASE_URL).rstrip("/")
    if base.endswith("/v1"):
        base = base[:-3]
    headers = {"Authorization": f"Bearer {api_key}"} if api_key else {}
    if requests is not None:
        for path, list_key in (("/api/v1/models", "models"), ("/v1/models", "data")):
            try:
                r = requests.get(f"{base}{path}", headers=headers, timeout=5)
                if r.status_code != 200:
                    continue
                keys = []
                for m in r.json().get(list_key) or []:
                    key = m.get("key") or m.get("id") or m.get("name")
                    if key and "embed" not in str(key).lower():
                        keys.append(str(key))
                if keys:
                    return keys
            except Exception:
                pass
    return _fallback_models()


def _parse_model_selection(text, models):
    """
    Parse user input into a list of model keys.

    Accepts:
      all
      1 3 5          (1-based indices)
      1,3,5
      model/name     (exact key)
      mix of the above
    """
    text = (text or "").strip()
    if not text:
        return None
    if text.lower() in ("all", "*"):
        return list(models)

    tokens = [t.strip() for t in text.replace(",", " ").split() if t.strip()]
    chosen = []
    seen = set()
    for tok in tokens:
        if tok.isdigit():
            idx = int(tok)
            if 1 <= idx <= len(models):
                key = models[idx - 1]
                if key not in seen:
                    chosen.append(key)
                    seen.add(key)
            else:
                raise ValueError(
                    f"Index {idx} out of range (1–{len(models)})."
                )
        else:
            # exact match, then case-insensitive, then unique substring
            if tok in models:
                key = tok
            else:
                lower = tok.lower()
                exact = [m for m in models if m.lower() == lower]
                if exact:
                    key = exact[0]
                else:
                    partial = [m for m in models if lower in m.lower()]
                    if len(partial) == 1:
                        key = partial[0]
                    elif not partial:
                        raise ValueError(f"Unknown model: {tok!r}")
                    else:
                        raise ValueError(
                            f"Ambiguous model {tok!r}; matches: "
                            + ", ".join(partial)
                        )
            if key not in seen:
                chosen.append(key)
                seen.add(key)
    return chosen


def _format_model_list(models, selected=None):
    selected = set(selected or [])
    lines = []
    for i, m in enumerate(models, 1):
        mark = "[x]" if m in selected else "[ ]"
        lines.append(f"  {i:2d}. {mark}  {m}")
    return "\n".join(lines)


def _argv_from_config(cli, settings_keys):
    """Build sys.argv from current config; expand list values correctly."""
    argv = [sys.argv[0]]
    for name, meta in cli.arg_meta.items():
        flag = meta.get("flag")
        if not flag:
            continue
        val = cli.config.get(name)
        if val is None:
            continue
        if meta.get("is_flag"):
            if val:
                argv.append(flag)
            continue
        if isinstance(val, (list, tuple)):
            if not val:
                continue
            argv.append(flag)
            argv.extend(str(v) for v in val)
        else:
            # space-separated multi-values stored as a single string
            argv.extend([flag, str(val)])
    return argv


def _resolve_summary_path(results_name):
    """Locate the summary CSV next to the results file (cwd or REPO_PATH)."""
    name = results_name or "coding_benchmark_results.csv"
    candidates = [
        Path(name),
        Path.cwd() / name,
        Path(REPO_PATH) / name,
    ]
    for p in candidates:
        summary = p.with_name(p.stem + "_summary.csv")
        if summary.exists():
            return summary
        # Also accept the summary path given directly
        if p.name.endswith("_summary.csv") and p.exists():
            return p
    # Default expected path even if missing
    return Path(name).with_name(Path(name).stem + "_summary.csv")


def _models_in_summary(summary_path):
    if summary_path is None or not Path(summary_path).exists():
        return []
    try:
        import pandas as pd

        df = pd.read_csv(summary_path, usecols=["model"])
        return sorted(df["model"].astype(str).unique())
    except Exception:
        try:
            import csv

            with open(summary_path, newline="", encoding="utf-8") as f:
                rows = csv.DictReader(f)
                return sorted({r["model"] for r in rows if r.get("model")})
        except Exception:
            return []


def build_cli():
    # .clizard is optional and only supplies cosmetic overrides (app_name,
    # ascii_art, accent_color, tips, updates). Settings/arg_meta/call_style
    # are baked into this file directly, so clizard_main.py works standalone
    # with no .clizard file required.
    clz = load_clizard_file(REPO_PATH)

    settings = dict(_DEFAULT_SETTINGS)
    arg_meta = {k: dict(v) for k, v in _DEFAULT_ARG_META.items()}
    call_style = _DEFAULT_CALL_STYLE

    # Prefill model choices from LM Studio (or fallback list) so /settings
    # and /models can show what is available.
    base_url = settings.get("base_url") or _DEFAULT_BASE_URL
    available = list_available_models(base_url, settings.get("api_key"))
    if available:
        arg_meta["models"]["choices"] = available

    # When a previous summary CSV exists, auto-check *all* available models
    # so /run continues the full campaign without a manual /models all.
    summary_path = _resolve_summary_path(settings.get("results"))
    auto_msg = None
    if summary_path.exists() and available:
        settings["models"] = list(available)
        in_summary = set(_models_in_summary(summary_path))
        lines = [
            f"Found summary: {summary_path}",
            f"Auto-selected all {len(available)} available model(s):",
        ]
        for m in available:
            short = str(m).split("/")[-1]
            tag = " [in summary]" if (short in in_summary or str(m) in in_summary) else ""
            lines.append(f"  [x] {m}{tag}")
        lines.append("Use /models to change the selection.")
        auto_msg = "\n".join(lines)

    cli = GenericCLI(
        app_name=clz.get("app_name") or "localbenchmark",
        ascii_art=clz.get("ascii_art"),
        accent_color=clz.get("accent_color", "#d97757"),
        settings=settings,
        tips=clz.get("tips") or _DEFAULT_TIPS,
        updates=clz.get("updates"),
    )
    cli.arg_meta = arg_meta

    if auto_msg:
        print(auto_msg)

    @cli.command("/status", "Show selected models and summary status")
    def _cmd_status(prompt):
        base = cli.config.get("base_url") or _DEFAULT_BASE_URL
        models = list_available_models(base, cli.config.get("api_key"))
        selected = cli.config.get("models") or []
        if isinstance(selected, str):
            selected = selected.split()
        sp = _resolve_summary_path(cli.config.get("results"))
        in_summary = set(_models_in_summary(sp)) if sp.exists() else set()
        lines = [
            f"Summary: {sp} "
            + ("(found)" if sp.exists() else "(not found)"),
            f"Selected ({len(selected)}):",
        ]
        for m in models:
            mark = "[x]" if m in selected else "[ ]"
            short = str(m).split("/")[-1]
            tag = (
                " [in summary]"
                if (short in in_summary or str(m) in in_summary)
                else ""
            )
            lines.append(f"  {mark} {m}{tag}")
        cli.assistant_message("\n".join(lines))

    @cli.command(
        "/models",
        "List models and select which to run "
        "(e.g. /models 1 3, /models all, /models name)",
    )
    def _cmd_models(prompt):
        base = cli.config.get("base_url") or _DEFAULT_BASE_URL
        models = list_available_models(base, cli.config.get("api_key"))
        if not models:
            cli.assistant_message(
                "No models found.\n"
                f"Is the server (LM Studio, llama.cpp, vLLM, Ollama, ...) running at {base}?\n"
                "Start the server, then try /models again."
            )
            return

        # Keep choices in sync for /settings
        cli.arg_meta.setdefault("models", {})["choices"] = models

        current = cli.config.get("models")
        if isinstance(current, str):
            current = current.split()
        elif current is None:
            current = []

        header = (
            f"Available models ({len(models)}) at {base}\n"
            f"{_format_model_list(models, selected=current)}\n"
        )

        selection = (prompt or "").strip()
        if not selection:
            cli.assistant_message(
                header
                + "\nSelect with:\n"
                "  /models all\n"
                "  /models 1 3 5\n"
                "  /models openai/gpt-oss-20b\n"
                "  /models 1,2  (comma or space separated)"
            )
            return

        try:
            chosen = _parse_model_selection(selection, models)
        except ValueError as exc:
            cli.assistant_message(f"{header}\nError: {exc}")
            return

        if not chosen:
            cli.assistant_message(header + "\nNo models selected.")
            return

        cli.config["models"] = chosen
        cli.assistant_message(
            "Selected models for the next /run:\n"
            + _format_model_list(models, selected=chosen)
            + f"\n({len(chosen)} model(s) selected)"
        )

    @cli.command("/run", "Run localbenchmark.main() with current settings")
    def _cmd_run(prompt):
        # Refresh model list so a stale None still can run defaults downstream
        models = cli.config.get("models")
        if models is None:
            cli.assistant_message(
                "No models selected: every available model will be tested. "
                "Use /models to pick specific ones."
            )
            # Still allow run: main() tests all available models when --models is omitted
        cli.status("Running...")
        if call_style == "argv":
            # main() takes no arguments and parses its own argparse
            # parser internally -- rebuild sys.argv from settings instead.
            argv = _argv_from_config(cli, settings)
            old_argv = sys.argv
            sys.argv = argv
            try:
                result = _original_main()
            finally:
                sys.argv = old_argv
        else:
            call_kwargs = {k: cli.config.get(k) for k in settings}
            result = _original_main(**call_kwargs)
        if result is not None:
            cli.assistant_message(str(result))

    return cli


def main():
    build_cli().run()


if __name__ == "__main__":
    main()
